package run.ikaros.identity; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/auth") public class AuthenticationController{private final AuthenticationService service;public AuthenticationController(AuthenticationService s){service=s;}@PostMapping("/register") public Mono<AuthenticationView> register(@Valid @RequestBody RegisterRequest q){return service.register(q);}@PostMapping("/login") public Mono<AuthenticationView> login(@Valid @RequestBody LoginRequest q){return service.login(q);}}
